"""After forge sync, as an upgrade runs it, Forge's generated files agree with themselves: the Codex
config's comment says what it sets, and CLAUDE.md moves into AGENTS.md without Forge's own lines."""
from __future__ import annotations

import re
import shutil
import tomllib

import pytest

import conftest
from test_setup import _on_a_branch_with_forge_toml, _version

STORY = "upgrade-files-agree"
TEAM = ["- Keep the checkout script fast.", "## Payments", "- Never log card numbers."]
# Lines Forge itself wrote in earlier releases: its generated stub, its import line and two rules
# this release replaces (the merge rule now depends on forge.toml's merge setting).
FORGE_OLD = [
    "<!-- Generated by forge sync. Edit outside the forge:begin and forge:end lines; "
    "sync rewrites this block. -->",
    "@AGENTS.md",
    "- Never merge a pull request and never use `--no-verify`. Merging is the human's call.",
    "- Ask the human only to approve a story, to choose between options, or to merge.",
]
# The team's own note, then the comment an earlier Forge wrote above the sandbox setting.
TEAM_NOTE = "# Our CI box has no network, so keep this in step with ci.yml.\n"
STALE = ("# Workspace-write by default (decision 0041). Needing broader access means\n"
         "# editing this value deliberately in the client repo — the diff-visible edit\n"
         "# is the ledgered escape hatch, and `forge upgrade` restores this default.\n")


def _new(repo):
    _on_a_branch_with_forge_toml(repo)


def _adopted_on_an_earlier_release(repo):
    shutil.copytree(conftest.ROOT / "tests/fixtures/adopted-v1.2.2/client", repo.path,
                    dirs_exist_ok=True)
    repo.git("checkout", "-q", "-b", "fix/upgrade")
    # What forge upgrade does before it runs the release's sync.
    toml = (repo.path / "forge.toml").read_text(encoding="utf-8")
    repo.write("forge.toml", toml.replace('"v1.2.2"', f'"{_version(repo)}"'))
    config = (repo.path / ".codex/config.toml").read_text(encoding="utf-8")
    repo.write(".codex/config.toml", TEAM_NOTE + STALE + config.replace('"danger-full-access"', '"workspace-write"'))


@pytest.mark.parametrize("setup", [_new, _adopted_on_an_earlier_release])
def test_1_synced_files_say_what_they_set_and_claude_md_moves_only_the_team_s_lines(repo, setup):
    setup(repo)
    claude = "\n\n".join([FORGE_OLD[0], "# Shop", FORGE_OLD[1], TEAM[0], *FORGE_OLD[2:], *TEAM[1:]])
    repo.write("CLAUDE.md", claude + "\n")
    repo.git("add", "-A")
    repo.git("commit", "-q", "-m", "The repo before sync")

    done = repo.forge("sync")
    assert done.returncode == 0, done.stdout + done.stderr

    assert not (repo.path / "CLAUDE.md").exists()
    agents = (repo.path / "AGENTS.md").read_text(encoding="utf-8")
    moved = agents.split("<!-- forge:end -->", 1)[1]
    assert all(line in moved for line in TEAM), moved
    assert not any(line in moved for line in FORGE_OLD), moved
    assert "Never merge a pull request" not in agents

    text = (repo.path / ".codex/config.toml").read_text(encoding="utf-8")
    assert tomllib.loads(text)["sandbox_mode"] == "danger-full-access"
    above = re.search(r"((?:^#.*\n)*)^sandbox_mode", text, re.M)[1]
    assert "full access" in above and "workspace" not in text.lower(), text
    if setup is _adopted_on_an_earlier_release:
        assert above.startswith(TEAM_NOTE), text
    assert repo.forge("sync").stdout.startswith("Nothing to change")
